<?php require_once '../config/database.php';require_once '../includes/functions.php';$base='../';$items=[];$total=0;if(!empty($_SESSION['cart'])){$ids=array_map('intval',array_keys($_SESSION['cart']));$ph=implode(',',array_fill(0,count($ids),'?'));$s=$conn->prepare("SELECT id,name,price,image,stock FROM products WHERE id IN ($ph)");$s->bind_param(str_repeat('i',count($ids)),...$ids);$s->execute();$r=$s->get_result();while($p=$r->fetch_assoc()){$p['qty']=min($p['stock'],(int)$_SESSION['cart'][$p['id']]);$p['sub']=$p['qty']*$p['price'];$total+=$p['sub'];$items[]=$p;}}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);else foreach($_POST['qty']??[] as $id=>$q)$_SESSION['cart'][(int)$id]=max(1,(int)$q);header('Location: cart.php');exit;}$pageCss='keranjang.css';include '../includes/header.php';?>
<main><section class="pagehero compact"><span class="eyebrow">YOUR LITTLE TREASURES</span><h1>Your <em>basket.</em></h1></section><section class="section"><?php if(!$items):?><div class="empty"><h2>Keranjang masih kosong</h2><a class="btn dark" href="katalog.php">Lihat koleksi</a></div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="cart-layout"><div><?php foreach($items as $p):?><div class="cart-row"><img src="<?=e(product_image_url($p['image'], $p['name']))?>" alt=""><div><h3><?=e($p['name'])?></h3><p><?=rp($p['price'])?></p><label>Qty <input type="number" name="qty[<?=$p['id']?>]" value="<?=$p['qty']?>" min="1" max="<?=$p['stock']?>"></label></div><button name="remove" value="<?=$p['id']?>" class="remove">Hapus</button></div><?php endforeach;?></div><aside class="summary"><h2>Ringkasan</h2><p>Total <b><?=rp($total)?></b></p><button class="btn outline">Perbarui</button><a class="btn dark full" href="checkout.php">Lanjut checkout ↗</a></aside></div></form><?php endif;?></section></main><?php include '../includes/footer.php';?>
